public class Main {
    public static void main(String[] args) throws Exception {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        int n = Integer.parseInt(br.readLine().trim());

        // Use an ArrayList as a stack to store slime values
        ArrayList<Integer> stack = new ArrayList<>();

        for (int i = 0; i < n; i++) {
            // Add a new slime of value 1
            stack.add(1);
            int size = stack.size();

            // While last two slimes have same value, merge them
            while (size >= 2 && stack.get(size - 1).equals(stack.get(size - 2))) {
                int newVal = stack.get(size - 1) + 1;
                // Remove last two
                stack.remove(size - 1);
                stack.remove(size - 2);
                // Add merged slime
                stack.add(newVal);
                size = stack.size();
            }
        }

        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < stack.size(); i++) {
            if (i > 0) sb.append(' ');
            sb.append(stack.get(i));
        }
        System.out.println(sb.toString());
    }
}

