        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        int n = Integer.parseInt(br.readLine().trim());

        // Use a stack to simulate the process
        // Maximum size is bounded by log2(n) ~ 17 for 100000, but we can safely use n
        int[] stack = new int[n * 2];
        int top = 0;

        for (int i = 0; i < n; i++) {
            // Add a slime with value 1
            stack[top++] = 1;

            // While last two slimes have same value, merge them
            while (top >= 2 && stack[top - 1] == stack[top - 2]) {
                int v = stack[top - 1] + 1;
                top -= 2;
                stack[top++] = v;
            }
        }

        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < top; i++) {
            if (i > 0) sb.append(' ');
            sb.append(stack[i]);
        }
        System.out.println(sb.toString());
    }
}

